// Inputs arrive in the order the Merge node received them: GA4, GSC now, GSC a year earlier.
// Any missing figure aborts the run: a failed refresh must never publish seed or zero values.
const items = $input.all();
const ga4 = items[0].json, now = items[1].json, prev = items[2].json;

// GA4: sum sessions per date range. With two dateRanges GA4 appends a 'dateRange' dimension, so row.dimensionValues = [source, range].
let cur = 0, before = 0;
for (const r of ga4.rows || []) {
  const range = (r.dimensionValues[1] || {}).value; // 'current' | 'previous'
  const n = Number(r.metricValues[0].value || 0);
  if (range === 'previous') before += n; else cur += n;
}
if (!(ga4.rows || []).length) throw new Error('GA4 returned no rows for the LLM referrer filter. Check GA4_PROPERTY_ID and the sessionSource pattern.');
if (before <= 0) throw new Error('GA4 previous-12-month LLM sessions are zero; a multiplier cannot be computed.');
const multiplier = Math.round((cur / before) * 10) / 10;

const rowNow = (now.rows || [])[0], rowPrev = (prev.rows || [])[0];
if (!rowNow || !rowPrev) throw new Error('Search Console returned no rows for one of the two windows. Check GSC_SITE_URL and the credential scope.');

// Keep the manually tracked tool counts from the file already in the repo.
// The GitHub node returns the contents-API envelope, so the file body is base64 in `content`.
const fileItem = $('Read current live.json').first().json;
let existing;
try { existing = JSON.parse(Buffer.from(fileItem.content, 'base64').toString('utf8')).tools; } catch (e) { existing = undefined; }
if (!existing || typeof existing.queryFanOut !== 'number') throw new Error('Could not read tools.* from the current live.json; refusing to overwrite it.');

return [{ json: {
  updatedAt: $today.toFormat('yyyy-MM-dd'),
  updatedBy: 'n8n weekly refresh',
  note: 'Written by automation/n8n-live-metrics.json. Raw numbers only; the templates format them.',
  llm: { multiplier, window: '12 months', source: 'GA4', sessions: cur, sessionsBefore: before },
  gsc: {
    impressionsBefore: Math.round(rowPrev.impressions), impressions: Math.round(rowNow.impressions),
    clicks: Math.round(rowNow.clicks),
    avgPositionBefore: Math.round(rowPrev.position * 10) / 10, avgPosition: Math.round(rowNow.position * 10) / 10,
    window: '3 months vs a year earlier'
  },
  tools: existing
} }];
